import json, hashlib, os, re
from pathlib import Path

def sha256(path):
    h = hashlib.sha256()
    with open(path, 'rb') as f:
        for chunk in iter(lambda: f.read(1 << 20), b''):
            h.update(chunk)
    return h.hexdigest()

def read_text(path):
    return Path(path).read_text(encoding='utf-8', errors='replace')

def parse_energy(path):
    text = read_text(path)
    vals = re.findall(r'FINAL SINGLE POINT ENERGY\s+(-?\d+\.\d+)', text)
    if not vals:
        vals = re.findall(r'Total Energy\s*:\s*(-?\d+\.\d+)', text)
    if not vals:
        raise ValueError(f'No final single point energy found in {path}')
    return float(vals[-1])

paths = {
    'gas_input': 'gas_job.inp',
    'gas_output': 'gas_stdout.out',
    'cpcm_input': 'cpcm_job.inp',
    'cpcm_output': 'cpcm_stdout.out',
    'shared_xyz': 'ethanol.xyz',
}
for p in paths.values():
    if not os.path.exists(p):
        raise FileNotFoundError(p)

e_gas = parse_energy(paths['gas_output'])
e_cpcm = parse_energy(paths['cpcm_output'])
delta = (e_cpcm - e_gas) * 2625.499639
hashes = {k: sha256(v) for k, v in paths.items()}

