        {'name': 'energy_cpcm', 'value': e_cpcm, 'unit': 'Eh', 'sources': [{'filename': paths['cpcm_output'], 'location': 'FINAL SINGLE POINT ENERGY'}], 'formula': None, 'artifacts': [paths['cpcm_output']], 'limitations': ['C-PCM water single-point electronic energy; no thermal corrections.']},
