        {'name': 'raw_input_output', 'value': raw, 'unit': None, 'sources': [{'filename': v, 'location': None} for v in paths.values()], 'formula': None, 'artifacts': list(paths.values()), 'limitations': ['Hashes are SHA-256 of the task-local copies listed.']},
